import { useState } from "react";



/**
 * 게시글 등록 버튼을 클릭하면 입력한 제목, 작성자, 내용이 콘솔에 출력되도록 작성
 */
function MapApp2(){
	
	let [num, setNum] = useState(2);
	let [posts, setPosts] =  useState([
		{ num : 1, title : '제목입니다', content : '내용입니다', writer : '홍길동'},
	]);
	let body = posts.map((item, index, arr)=>{
		return;
	});
	const postInsert = (e)=>{
		e.preventDefault();
		console.log(title);
		console.log(writer);
		console.log(content);
	}

	let [title, setTitle] = useState("");
	let [writer, setWriter] = useState("");
	let [content, setContent] = useState("");
	const titleChange = (e) => setTitle(e.target.value);
	const writerChange = (e) => setWriter(e.target.value);
	const contentChange = (e) => setContent(e.target.value);

	return(
		
		<div>
			<form onSubmit={postInsert}>
				<input type="text" placeholder="제목을 입력하세요." onChange={titleChange}/>
				<br />
				<input type="text" placeholder="작성자를 입력하세요." onChange={writerChange}/>
				<br />
				<textarea placeholder="내용을 입력하세요." onChange={contentChange}></textarea>
				<button onClick={postInsert}>게시글 등록</button>
			</form>
			<h1>게시글 목록</h1>
			<table>
				<thead>
					<tr>
						<th>번호</th>
						<th>제목</th>
						<th>작성자</th>
					</tr>
					{
						posts.map(item=>{
							return (
							<tr>
								<th>{item.num}</th>
								<th>{item.title}</th>
								<th>{item.writer}</th>
							</tr>
							)
						})
					}
				</thead>
				<tbody>
					{
						posts.map(item=>{
							return(
								<tr key={"post"+item.num}>
								<th>{item.num}</th>
								<th>{item.title}</th>
								<th>{item.writer}</th>
							</tr>
							);
						})
					}
				</tbody>
			</table>
		</div>
	);
}

export default MapApp2;
